create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null check (char_length(display_name) between 1 and 60), avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.touring_groups (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 2 and 80), invite_code text not null unique default upper(substr(encode(gen_random_bytes(6), 'hex'), 1, 6)), owner_id uuid not null references public.profiles(id) on delete cascade, status text not null default 'waiting' check (status in ('waiting', 'active', 'finished')), created_at timestamptz not null default now());
create table public.group_members (group_id uuid not null references public.touring_groups(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role text not null default 'member' check (role in ('leader', 'member')), joined_at timestamptz not null default now(), primary key (group_id, user_id));
create table public.live_locations (group_id uuid not null references public.touring_groups(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, latitude double precision not null check (latitude between -90 and 90), longitude double precision not null check (longitude between -180 and 180), accuracy double precision, speed double precision, heading double precision, updated_at timestamptz not null default now(), primary key (group_id, user_id));
create index live_locations_group_updated_idx on public.live_locations(group_id, updated_at desc); create index group_members_user_idx on public.group_members(user_id);
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles (id, display_name) values (new.id, coalesce(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), split_part(new.email, '@', 1))); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create function public.add_group_owner() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.group_members (group_id, user_id, role) values (new.id, new.owner_id, 'leader'); return new; end; $$;
create trigger on_group_created after insert on public.touring_groups for each row execute function public.add_group_owner();
create function public.is_group_member(target_group_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.group_members where group_id = target_group_id and user_id = auth.uid()); $$;
create function public.join_touring_group(code text) returns public.touring_groups language plpgsql security definer set search_path = '' as $$ declare selected_group public.touring_groups; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into selected_group from public.touring_groups where invite_code = upper(trim(code)); if selected_group.id is null then raise exception 'Kode grup tidak ditemukan'; end if; insert into public.group_members (group_id, user_id) values (selected_group.id, auth.uid()) on conflict do nothing; return selected_group; end; $$;
revoke all on function public.join_touring_group(text) from public; grant execute on function public.join_touring_group(text) to authenticated; grant execute on function public.is_group_member(uuid) to authenticated;
alter table public.profiles enable row level security; alter table public.touring_groups enable row level security; alter table public.group_members enable row level security; alter table public.live_locations enable row level security;
create policy "profiles readable by authenticated users" on public.profiles for select to authenticated using (true); create policy "users update own profile" on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
create policy "members read their groups" on public.touring_groups for select to authenticated using (public.is_group_member(id)); create policy "users create owned groups" on public.touring_groups for insert to authenticated with check (owner_id = auth.uid()); create policy "leaders update groups" on public.touring_groups for update to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy "members read group membership" on public.group_members for select to authenticated using (public.is_group_member(group_id)); create policy "users leave a group" on public.group_members for delete to authenticated using (user_id = auth.uid() and role <> 'leader');
create policy "members read group locations" on public.live_locations for select to authenticated using (public.is_group_member(group_id)); create policy "members insert own location" on public.live_locations for insert to authenticated with check (user_id = auth.uid() and public.is_group_member(group_id)); create policy "members update own location" on public.live_locations for update to authenticated using (user_id = auth.uid() and public.is_group_member(group_id)) with check (user_id = auth.uid() and public.is_group_member(group_id)); create policy "users delete own location" on public.live_locations for delete to authenticated using (user_id = auth.uid());
alter publication supabase_realtime add table public.live_locations;
